          "color": "color-cream",
          "altura": "tall",
          "patron": "pattern-ribbon",
          "inclinacion": "",
          "icono": "🍓",
          "contenidoTexto": "Federico Brac\n\nNo te das una idea de cómo con algo tan simple y lejano como una foto mi cara se llena de brillo de solo pensar que puedo decirte sin apuro ni complejos que te amo, saber que toda tu personalidad, presencia, humor y pensar me hizo un lugar para habitar en tu corazón.",
