const PALETA_COLORES = [
    "color-red", "color-pink", "color-mint", "color-cream", 
    "color-burgundy", "color-navy", "color-gold", "color-forest"
];
const PATRONES = ["", "pattern-stripes", "pattern-dots", "pattern-ribbon"];
const ALTURAS = ["short", "medium", "tall"];
const INCLINACIONES = ["", "", "", "tilted-left", "tilted-right"];
const ICONOS_EMOJI = ["🍓", "🌿", "☕", "📜", "⭐", "📖", "✨", "🌸", "🍂", "🕊️"];

const BibliotecaManager = {
    STORAGE_KEY: "biblioteca_luz_drive_v3_completa",
    CONFIG_KEY: "biblioteca_luz_config_v3_completa",

    obtenerCatalogo: function() {
        try {
            const guardado = localStorage.getItem(this.STORAGE_KEY);
            if (guardado) {
                const parseado = JSON.parse(guardado);
                // Solo usar si tiene al menos 24 categorías completas
                if (parseado && parseado.categorias && parseado.categorias.length >= 24) {
                    return parseado;
                }
            }
        } catch (e) {
            console.warn("Error leyendo LocalStorage:", e);
        }
        // Cargar inmediatamente la colección completa de Google Drive con 504 libros
        this.guardarCatalogo(BIBLIOTECA_DRIVE_DATA);
        return BIBLIOTECA_DRIVE_DATA;
    },

    guardarCatalogo: function(datos) {
        try {
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(datos));
        } catch (e) {
            console.error("Error guardando catálogo:", e);
        }
    },

    guardarConfig: function(config) {
        localStorage.setItem(this.CONFIG_KEY, JSON.stringify(config));
    },

    obtenerConfig: function() {
        try {
            const config = localStorage.getItem(this.CONFIG_KEY);
            return config ? JSON.parse(config) : {
                driveUrl: "https://drive.google.com/drive/folders/1M4rZbtBV-aKu2NgnFUpkL4TZzbxAFqz3",
                carpetaId: "1M4rZbtBV-aKu2NgnFUpkL4TZzbxAFqz3",
                scriptUrl: "",
                sincronizado: true
            };
        } catch (e) {
            return { sincronizado: true };
        }
    },

    restaurarPorDefecto: function() {
        localStorage.removeItem(this.STORAGE_KEY);
        return BIBLIOTECA_DRIVE_DATA;
    },

    sincronizarDesdeGoogleDrive: async function(urlEndpoint) {
        if (!urlEndpoint) {
            throw new Error("Por favor ingresa la URL de la aplicación web de Google Apps Script.");
        }

        const respuesta = await fetch(urlEndpoint, {
            method: 'GET',
            mode: 'cors'
        });

        if (!respuesta.ok) {
            throw new Error(`Error HTTP ${respuesta.status} al conectar con Google Apps Script.`);
        }

        const datosDrive = await respuesta.json();
        if (datosDrive.status === "error") {
            throw new Error(datosDrive.message);
        }

        const categoriasEstilizadas = datosDrive.categorias.map((cat, idxCat) => {
            const librosEstilizados = cat.libros.map((libro, idxLibro) => {
                const seed = (idxCat * 13 + idxLibro * 7);
                return {
                    id: libro.id,
                    titulo: libro.titulo,
                    autor: cat.nombre,
                    color: PALETA_COLORES[seed % PALETA_COLORES.length],
                    altura: ALTURAS[seed % ALTURAS.length],
                    patron: PATRONES[(seed + 1) % PATRONES.length],
                    inclinacion: INCLINACIONES[(seed + 2) % INCLINACIONES.length],
                    icono: (seed % 3 === 0) ? ICONOS_EMOJI[seed % ICONOS_EMOJI.length] : "",
                    tipo: "drive-pdf",
                    urlVistaPrevia: libro.urlVistaPrevia,
                    urlDirecta: libro.urlDirecta,
                    urlDrive: libro.urlDrive,
                    nombreArchivo: libro.nombreArchivo,
                    tamanoBytes: libro.tamanoBytes
                };
            });

            return {
                id: cat.id || `drive-cat-${idxCat}`,
                nombre: cat.nombre,
                icono: ICONOS_EMOJI[idxCat % ICONOS_EMOJI.length] || "📚",
                descripcion: `${librosEstilizados.length} libros en Google Drive.`,
                libros: librosEstilizados
            };
        });

        // Añadir los poemas de fresas como primera categoría
        categoriasEstilizadas.unshift(original_poems);

        const nuevoCatalogo = {
            nombre: datosDrive.bibliotecaNombre || "Gran Biblioteca de Luz",
            driveUrl: "https://drive.google.com/drive/folders/1M4rZbtBV-aKu2NgnFUpkL4TZzbxAFqz3",
            fuente: "Google Drive Live",
            ultimaSincronizacion: new Date().toISOString(),
            totalLibros: categoriasEstilizadas.reduce((acc, c) => acc + c.libros.length, 0),
            totalCategorias: categoriasEstilizadas.length,
            categorias: categoriasEstilizadas
        };

        this.guardarCatalogo(nuevoCatalogo);
        this.guardarConfig({
            scriptUrl: urlEndpoint,
            sincronizado: true,
            fecha: new Date().toLocaleDateString()
        });

        return nuevoCatalogo;
    },

    importarCarpetaLocal: async function(archivos) {
        const mapaCategorias = {};
        for (let i = 0; i < archivos.length; i++) {
            const archivo = archivos[i];
            const ruta = archivo.webkitRelativePath || archivo.name;
            const partes = ruta.split('/');
            if (partes.length < 2) continue;
            const nombreArchivo = partes[partes.length - 1];
            if (!nombreArchivo.match(/\.(pdf|epub|txt|doc|docx)$/i)) continue;

            const nombreCategoria = partes.length > 2 ? partes[1] : "General";
            if (!mapaCategorias[nombreCategoria]) {
                mapaCategorias[nombreCategoria] = [];
            }

            const objectUrl = URL.createObjectURL(archivo);
            const titulo = nombreArchivo.replace(/\.(pdf|epub|txt|doc|docx)$/i, '');

            mapaCategorias[nombreCategoria].push({
                id: `local-${i}-${Date.now()}`,
                titulo: titulo,
                autor: "Archivo Local",
                tipo: "local-file",
                urlVistaPrevia: objectUrl,
                nombreArchivo: nombreArchivo,
                tamanoBytes: archivo.size
            });
        }

        const categoriasNuevas = Object.keys(mapaCategorias).map((nombreCat, idxCat) => {
            const libros = mapaCategorias[nombreCat].map((libro, idxLibro) => {
                const seed = (idxCat * 17 + idxLibro * 11);
                return {
                    ...libro,
                    color: PALETA_COLORES[seed % PALETA_COLORES.length],
                    altura: ALTURAS[seed % ALTURAS.length],
                    patron: PATRONES[seed % PATRONES.length],
                    inclinacion: INCLINACIONES[seed % INCLINACIONES.length],
                    icono: (seed % 3 === 0) ? ICONOS_EMOJI[seed % ICONOS_EMOJI.length] : ""
                };
            });

            return {
                id: `local-cat-${idxCat}`,
                nombre: nombreCat,
                icono: "📂",
                descripcion: `${libros.length} libros importados localmente.`,
                libros: libros
            };
        });

        if (categoriasNuevas.length === 0) {
            throw new Error("No se encontraron libros PDF en la carpeta.");
        }

        const nuevoCatalogo = {
            nombre: "Biblioteca Local",
            fuente: "Carpeta Local",
            ultimaSincronizacion: new Date().toISOString(),
            totalLibros: categoriasNuevas.reduce((acc, c) => acc + c.libros.length, 0),
            totalCategorias: categoriasNuevas.length,
            categorias: [original_poems].concat(categoriasNuevas)
        };

        this.guardarCatalogo(nuevoCatalogo);
        return nuevoCatalogo;
    }
};
